-- name: BackofficeListDomains :many
SELECT d.id,d.id AS asset_id,d.team_id,coalesce(t.name,'') AS team_name,d.normalized_name AS name,'team'::text AS owner_type,d.status AS asset_status,d.provider,d.provider_account,d.provider_region AS region,d.status,coalesce(d.provider_status,'') AS provider_status,d.status='verified' AS verified,d.health_status,d.reconciliation_attempts AS attempts,d.consecutive_health_failures,coalesce(d.last_error,'') AS last_error,d.last_checked_at,d.next_check_at,d.created_at,d.updated_at FROM domains d LEFT JOIN teams t ON t.id=d.team_id ORDER BY d.created_at DESC,d.id DESC LIMIT sqlc.arg(page_limit)::int OFFSET sqlc.arg(page_offset)::int;
-- name: BackofficeGetDomain :one
SELECT d.id,d.id AS asset_id,d.team_id,coalesce(t.name,'') AS team_name,d.normalized_name AS name,'team'::text AS owner_type,d.status AS asset_status,d.provider,d.provider_account,d.provider_region AS region,d.status,coalesce(d.provider_status,'') AS provider_status,d.status='verified' AS verified,d.health_status,d.reconciliation_attempts AS attempts,d.consecutive_health_failures,coalesce(d.last_error,'') AS last_error,d.last_checked_at,d.next_check_at,d.created_at,d.updated_at FROM domains d LEFT JOIN teams t ON t.id=d.team_id WHERE d.id=sqlc.arg(id);
